import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // Restrict: caller cannot be the owner; amount must be > 0 and avoid overflow
        vm.assume(caller != c.owner());
        amount = bound(amount, 1, address(this).balance / 2);

        // Fund the contract directly so it has a balance to steal
        vm.deal(address(c), amount);

        // Record owner's balance before
        uint256 ownerBefore = c.owner().balance;

        // Make the caller execute go()
        vm.prank(caller);
        c.go();

        // The contract should be empty after the transfer
        assertTrue(address(c).balance == 0);

        // The owner's balance must have increased by exactly the initial contract balance
        // (the mutant would instead leave the owner's balance unchanged)
        assertTrue(c.owner().balance == ownerBefore + amount);
    }
}

