pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Bound the amount to avoid overflow in arithmetic and keep it within reasonable limits
        amount = bound(amount, 1, address(c).balance + 100 ether);

        // Ensure the contract has some ether to work with
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool funded,) = payable(address(c)).call{value: amount}("");
        require(funded, "Funding failed");

        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Perform the call to go() with the fuzzed amount as msg.value from an arbitrary sender
        vm.deal(address(0x1234), amount);
        vm.prank(address(0x1234));
        c.go{value: amount}();

        uint256 ownerBalanceAfter = c.owner().balance;

        // Since we don't control the target, we assume the call succeeds (it's an EOA or contract without code)
        // In the reference, the owner receives the entire contract balance after the call.
        // In the buggy version, the owner receives nothing.
        // Assert that the owner's balance increased by exactly contractBalanceBefore + amount.
        assertEq(ownerBalanceAfter - ownerBalanceBefore, contractBalanceBefore + amount);
    }
}

